      "kind": "settlement",
      "name": "Camp Harmony",
      "description": "\"A shantytown of tents, tin shacks and gutted railcars, ringed by a fence of doors, bed frames and sheet tin. It’s ugly, crowded and smells of smoke, but it runs.\"",
